head.script:
/* ★Wcraft guide★    
스크립트 수작업 유의사항
*/


//★Wcraft guide★ include부분 주석처리 -> include("../js/PopupCalendar.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/libRoundPanel.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/list_common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/bns_common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/session.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/stf.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/utils.js");
scwin.vScrenID = "ULDBNS20005.xml";
scwin.fn_GetPar, scwin.fn_SetPar;
scwin.processGp;
scwin.vListDd = '';
scwin.vBndApplId = '';
scwin.vIsuNm = '';
scwin.vMktactTpCd = '';
scwin.vs_G_GB = ""; //팝업에 쓰임 
scwin.vs_G_GRP_PROCS_DD = ""; //
scwin.vs_G_GRP_PROCS_TM = ""; //
scwin.vs_G_BND_APPL_ID = ""; //
scwin.vs_G_BND_LIST_PROCS_TP_CD = ""; //	

scwin.vFeeTpCd = '';
scwin.vRowCount = 0;
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
};

/********************************************** 
 * 함수명   : fn_Search
 * 설명       : 기본정보를 조회한다.
 ***********************************************/
scwin.fn_Search = function() {
    var dsNm = 'BNS_ANULFEE_DTL';
    var qryId = "";
    var param = '';
    if (scwin.vs_G_GB == "01") {
        qryId = 'lds.stf.bnsnew.select.readFeeBasInfo01';
        param += '&{P}V_BND_APPL_ID=' + scwin.vs_G_BND_APPL_ID;
        param += '&{P}V_BND_LIST_PROCS_TP_CD=' + scwin.vs_G_BND_LIST_PROCS_TP_CD;
    } else {
        qryId = 'lds.stf.bnsnew.select.readFeeBasInfo03';
        param += '&{P}V_GRP_PROCS_DD=' + scwin.vs_G_GRP_PROCS_DD;
        param += '&{P}V_GRP_PROCS_TM=' + scwin.vs_G_GRP_PROCS_TM;
    }
    $c.bns.fn_SearchBns(scwin.vScrenID, dts_Anulfee, dsNm, qryId, param);
};


/********************************************** 
 * 함수명   : fn_SearchFee
 * 설명       : 수수료 조회한다.
 ***********************************************/
scwin.fn_SearchFee = function() {
    var param = '';
    param += '&{P}V_BND_APPL_ID=' + scwin.vBndApplId;
    param += '&{P}V_LIST_AMT=' + $c.stf.getObjectValue(edt_ListAmt);
    param += '&{P}V_REDMPT_DD=' + $c.stf.getObjectValue(edt_RedmptDd);
    param += '&{P}V_LIST_DD=' + $c.stf.getObjectValue(edt_ListDd);
    param += '&{P}V_CURR_TP_CD=' + $c.stf.getObjectValue(cmb_CurrTpCd);
    param += '&{P}V_EXCHG_RT=' + $c.stf.getObjectValue(edt_BasExchg);
    param += '&{P}V_BND_LIST_PROCS_TP_CD=' + '1';
    var dsNm = 'BNS_ANULFEE_DTL';
    var qryId = 'lds.stf.bnscommon.select.readCalcFee';
    $c.bns.fn_SearchBns(scwin.vScrenID, dts_Calc, dsNm, qryId, param);
};


/********************************************** 
 * 함수명   : fn_Save
 * 설명       : 상장수수료 및 연부과금에서  저장 시, 수정처리
 ***********************************************/
scwin.fn_Save = function() {
    if (scwin.fn_checkData() > 0) return;
    if (!window.confirm($c.stf.getMessageParam("MSG-A006", "수수료등록"))) return;

    /**
     * 	- 변경된 데이터가 없더라도 데이터셋 전송하여 접수 진행
     */
    dts_Anulfee.UseChangeInfo = "False";
    var url = "/bns/ListFeeAndAnulfee.do?method=updateNewListFee";
    url += "&SCREN_ID=" + scwin.vScrenID;
    url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_03;
    trs_Save.Action = $c.lc.fn_encodeNSession(url);
    trs_Save.KeyName = "toinb_dataid4";
    trs_Save.KeyValue = "JSP(I:pInput=dts_Anulfee)";
    trs_Save.Post();
};


/********************************************** 
 * 함수명   : fn_checkData
 * 설명       : 입력을 체크한다.
 ***********************************************/
scwin.fn_checkData = function() {
    if ($c.stf.getObjectValue(txb_IsuNm) == '') {
        $c.win.alert('등록할 데이타가 없습니다.');
        return 1;
    }
    if ($c.stf.getObjectValue(cmb_ListFeePayYn) == '') {
        $c.win.alert('상장수수료 납부여부 선택하십시오.');
        return 1;
    }
    if ($c.stf.getObjectValue(cmb_AnulfeePayYn) == '') {
        $c.win.alert('연부과금 납부여부 선택하십시오.');
        return 1;
    }
    if ($c.stf.getObjectValue(edt_BndAnulfee) == '') {
        $c.win.alert('연부과금 수수료금액을 입력하십시오.');
        return 1;
    }
    if ($c.stf.getObjectValue(edt_ListFee) == '') {
        $c.win.alert('상장수수료 수수료금액을 입력하십시오.');
        return 1;
    }
    if ($c.stf.getObjectValue(cmb_ListFeePayYn) == '3' &&
        $c.stf.getObjectValue(cmb_BndListFeeExmptRsnCd) == '') {
        $c.win.alert('상장수수료 면제시에는 면제사유를 선택하십시오.');
        return 1;
    }
    if ($c.stf.getObjectValue(cmb_ListFeePayYn) == '3' &&
        $c.stf.getObjectValue(edt_ListFee) != '0') {
        $c.win.alert('상장수수료 면제시에는 상장수수료를 0원으로 입력하십시오.');
        return 1;
    }
    if ($c.stf.getObjectValue(cmb_AnulfeePayYn) == '3' &&
        $c.stf.getObjectValue(cmb_BndAnulfeeExmptRsnCd) == '') {
        $c.win.alert('연부과금 면제시에는 면제사유를 선택하십시오.');
        return 1;
    }
    if ($c.stf.getObjectValue(cmb_AnulfeePayYn) == '3' &&
        $c.stf.getObjectValue(edt_BndAnulfee) != '0') {
        $c.win.alert('연부과금 면제시에는 연부과금액을 0원으로 입력하십시오.');
        return 1;
    }

    //상장수수료,연부과금 면제이면 입금일 체크하지 않는다.
    if ($c.stf.getObjectValue(cmb_ListFeePayYn) == 'E' && $c.stf.getObjectValue(cmb_AnulfeePayYn) == 'E') {
        return 0;
    }
    if ($c.stf.getObjectValue(edt_FeeDepoDd) == '') {
        $c.win.alert('입금일을 입력하십시오.');
        return 1;
    }
    if ($c.bns.fn_CheckDateObj(edt_FeeDepoDd, "입금일")) {
        return 1;
    }
    //메시지 추가 입금일이 오늘 이후 날짜일 경우 확인메시지 추가
    if ($c.stf.getObjectValue(edt_FeeDepoDd) > $c.ut.cGetToday('yyyymmdd')) {
        if (!window.confirm('입금일이 오늘 이후 날짜입니다. 계속 진행하시겠습니까?')) return 1;
    }
    return 0;
};


/********************************************** 
 * 함수명   : fn_Calc
 * 설명       : 수수료 수정계산
 ***********************************************/
scwin.fn_Calc = function() {
    if ($c.stf.getObjectValue(edt_ListAmt) == '' ||
        $c.stf.getObjectValue(edt_ListDd) == '' ||
        $c.stf.getObjectValue(edt_RedmptDd) == '') {
        $c.win.alert('상장금액, 상장일, 상환일을 확인하세요');
        return;
    }
    if ($c.stf.getObjectValue(cmb_CurrTpCd) != '' &&
        $c.stf.getObjectValue(cmb_CurrTpCd) != '1') {
        if ($c.stf.getObjectValue(edt_BasExchg) == '') {
            $c.win.alert('기준환율을 입력바랍니다.');
            return;
        }
    }
    scwin.fn_SearchFee();
};


/********************************************** 
 * 함수명   : fn_ExApply
 * 설명       : 환율적용 처리
 ***********************************************/
scwin.fn_ExApply = function() {
    if ($c.stf.getObjectValue(cmb_CurrTpCd) != '1') {
        if ($c.stf.getObjectValue(edt_BasExchg) == '') {
            $c.win.alert('기준환율을 입력바랍니다.');
            return;
        }
        scwin.vFeeTpCd = '1';
        scwin.fn_SearchFee();
    } else {
        $c.win.alert('외화표시채권일때만 선택합니다.');
        $c.stf.setObjectValue(edt_BasExchg, '');
    }
};



/********************************************** 
 * 함수명   : fn_SetParam
 * 설명       : 부모창에서 받은 데이터를 설정한다.
 ***********************************************/
scwin.fn_SetParam = function() {
    var prt = $c.frame.path("../");
    if (prt != undefined) {
        scwin.fn_GetPar = prt.scwin.fn_GetPar;
        scwin.fn_SetPar = prt.scwin.fn_SetPar;
    }
    if (scwin.fn_GetPar != undefined) {
        var arrPar = new Array();
        scwin.fn_GetPar(arrPar);
        scwin.vBndApplId = arrPar[0].BND_APPL_ID;
        scwin.vListDd = arrPar[0].LIST_DD;
        scwin.vIsuNm = arrPar[0].ISU_NM;
        scwin.vMktactTpCd = arrPar[0].MKTACT_TP_CD;
        scwin.vs_G_GRP_PROCS_DD = arrPar[0].GRP_PROCS_DD;
        scwin.vs_G_GRP_PROCS_TM = arrPar[0].GRP_PROCS_TM;
        scwin.vs_G_BND_APPL_ID = arrPar[0].BND_APPL_ID;
        scwin.vs_G_BND_LIST_PROCS_TP_CD = arrPar[0].BND_LIST_PROCS_TP_CD;
        scwin.vs_G_GB = arrPar[0].GRP_GB;
    }
};




/********************************************** 
 * 함수명   : fn_ExchMbr
 * 설명      : 거래소회원 체크 여부
 ***********************************************/
scwin.fn_ExchMbr = function() {
    if (dts_Anulfee.getCellData(1, "KSE_MEM_YN") == 'Y') {
        chk_KseMemYn.setValue(1);
    } else {
        chk_KseMemYn.setValue(0);
    }
};



/********************************************** 
 * 함수명   : fn_Close()
 * 설명      :팝업 닫기
 ***********************************************/
scwin.fn_Close = async function() {
    await $c.frame.CloseFrame();
};
scwin.dts_Anulfee_OnLoadError = function() {
    $c.win.alert($c.stf.getMessageParam("MSG-0002"));
};
scwin.gform_onload = function() {
    $c.bns.BnsPanelToGroupBox(pnl_Info);

    //공통콤보
    var arrCid = [];
    arrCid.push({
        cid: '02475',
        cnm: 'cmb_CurrTpCd'
    }); //발행통화
    $c.bns.fn_SetBnsComboToCode(scwin.vScrenID, dts_Temp, arrCid);

    //파라미터설정
    scwin.fn_SetParam();
    //Exa DB체크
    if (js_svrGubun == 'dr') {
        $c.win.alert("DR에서 운영될때는 서비스가 제공되지 않습니다.");
        //return false;

    } else {
        $c.bns.fn_BnsCheckExaDb(scwin.vScrenID, dts_CheckExa, '1');
    }

    //showObj(cmb_CurrTpCd, false);	//통화단위 숨기기(요청사항)
    //숨기기
    if (scwin.vs_G_GB == "01") {
        $c.stf.showObj(pnl_new, false);
    } else {
        $c.stf.showObj(pnl_org, false);
        $c.stf.showObj(btn_SearchEx, false);
        $c.stf.showObj(btn_Calc, false);
    }
    //조회
    $c.stf.showObj(label_6, false);
    $c.stf.showObj(chk_TrdYn, false);
    $c.stf.showObj(label_3, false);
    $c.stf.showObj(chk_KseMemYn, false);
    scwin.fn_Search();
};
scwin.btn_Save_onclick = function() {
    scwin.fn_Save();
};
scwin.btn_Calc_onclick = function() {
    scwin.fn_Calc();
};
scwin.btn_SearchEx_onclick = function() {
    var url = 'http://www.smbs.biz';
    window.open(url, "", "scrollbars=yes,toolbar=no,resizable=yes,left=0,top=0");
    //frame.Provider("/top").WinOpenP('INS05500');

};
scwin.bnt_ExApply_onclick = function() {
    scwin.fn_ExApply();
};
scwin.img_ListFeeRepayDd_onclick = function() {
    if (scwin.vRowCount == 0) return;
    popUpCalendar2(edt_ListFeeRepayDd);
};
scwin.img_AnulfeeRepayDd_onclick = function() {
    if (scwin.vRowCount == 0) return;
    popUpCalendar2(edt_AnulfeeRepayDd);
};
scwin.img_RedmptDd_onclick = function() {
    if (scwin.vRowCount == 0) return;
    popUpCalendar2(edt_RedmptDd);
};
scwin.img_ListDd_onclick = function() {
    if (scwin.vRowCount == 0) return;
    popUpCalendar2(edt_ListDd);
};
scwin.img_FeeDepoDd_onclick = function() {
    if (scwin.vRowCount == 0) return;
    popUpCalendar2(edt_FeeDepoDd);
};
scwin.dts_Anulfee_OnLoadCompleted = function(rowcount) {
    scwin.vRowCount = rowcount;
    $c.stf.setObjectValue(txb_ChrgNm, js_emp_nm);
    if (rowcount > 0) {
        if (scwin.vIsuNm != '') {
            $c.stf.setObjectValue(txb_IsuNm, scwin.vIsuNm);
        }

        //KRW이면 기준환율 입력불가
        if (dts_Anulfee.getCellData(1, 'CURR_TP_CD') == '1') {
            edt_BasExchg.setDisabled(true);
        }
        //수수료조회
        if (dts_Anulfee.getCellData(1, 'CHK_IDX') == 0) {
            scwin.fn_SearchFee();
        }
        scwin.fn_ExchMbr();
        /*
        //자동저장
        if(getObjectValue(cmb_ListFeePayYn) == 'E'
        	&& getObjectValue(cmb_AnulfeePayYn) == 'E') {
        	fn_Save();
        }
        */

    }
};
scwin.dts_Calc_OnLoadCompleted = function(rowcount) {
    if (rowcount > 0) {
        if ($c.stf.getObjectValue(cmb_BndListFeeExmptRsnCd) != '') {
            $c.stf.setObjectValue(edt_ListFee, '0');
            $c.stf.setObjectValue(edt_BndAnulfee, '0');
        }
        //환율적용
        else if (scwin.vFeeTpCd == '1') {
            scwin.vFeeTpCd = '';
            $c.stf.setObjectValue(edt_ListFee, dts_Calc.getCellData(1, 'LIST_FEE'));
        }
        //수정계산
        else {
            if ($c.stf.getObjectValue(cmb_CurrTpCd) != '1') {
                if (dts_Calc.getCellData(1, 'EXCHG_RT') != '') {
                    $c.stf.setObjectValue(edt_ListFee, dts_Calc.getCellData(1, 'LIST_FEE'));
                }
            } else {
                $c.stf.setObjectValue(edt_ListFee, dts_Calc.getCellData(1, 'LIST_FEE'));
            }

            //연부과금
            if ($c.stf.getObjectValue(cmb_AnulfeePayYn) == 'E') {
                $c.stf.setObjectValue(edt_BndAnulfee, '0');
            } else {
                $c.stf.setObjectValue(edt_BndAnulfee, dts_Calc.getCellData(1, 'BND_ANULFEE'));
            }
        }
        $c.stf.setObjectValue(txb_Term, dts_Calc.getCellData(1, 'TERM'));
        $c.stf.setObjectValue(edt_BasExchg, dts_Calc.getCellData(1, 'EXCHG_RT'));
    }
};
scwin.btn_Close_onclick = async function() {
    await $c.frame.CloseFrame();
};
scwin.edt_ListFee_OnKillFocus = function() {
    edt_ListFee.RightMargin = 5;
};
scwin.edt_BndAnulfee_OnKillFocus = function() {
    edt_BndAnulfee.RightMargin = 5;
};
scwin.edt_ListFeeRepayAmt_OnKillFocus = function() {
    edt_ListFeeRepayAmt.RightMargin = 5;
};
scwin.edt_AnulfeeRepayAmt_OnKillFocus = function() {
    edt_AnulfeeRepayAmt.RightMargin = 5;
};
scwin.trs_Save_OnFail = function() {
    $c.win.alert($c.stf.getMessageParam("MSG-0002"));
};
scwin.trs_Save_OnSuccess = function() {
    $c.win.alert($c.stf.getMessageParam("MSG-0001"));
    dts_Anulfee.Reset();
    var arrPar = new Array();
    arrPar[0] = {
        REG_YN: "Y"
    };
    scwin.fn_SetPar(arrPar);
};
